use clap::ValueEnum;
use strum::{Display, EnumIter};

#[derive(Debug, Clone, EnumIter, Display)]
pub enum DatabaseType {
    PostgreSQL,
    MySQL,
    Redis,
    MongoDB,
}

impl DatabaseType {
    pub fn to_slug(&self) -> &'static str {
        match self {
            DatabaseType::PostgreSQL => "postgres",
            DatabaseType::MySQL => "mysql",
            DatabaseType::Redis => "redis",
            DatabaseType::MongoDB => "mongo",
        }
    }
}

impl ValueEnum for DatabaseType {
    fn value_variants<'a>() -> &'a [Self] {
        &[Self::PostgreSQL, Self::MySQL, Self::Redis, Self::MongoDB]
    }

    fn to_possible_value(&self) -> Option<clap::builder::PossibleValue> {
        Some(clap::builder::PossibleValue::new(self.to_slug()))
    }
}

/// Waits for a workflow to complete by polling workflowStatus.
///
/// `Running` (and unknown statuses) keep polling, and so does `NotFound` --
/// tolerating read-after-write lag right after the workflow was created.
/// `Error` is terminal: a workflow that has already failed never un-fails,
/// so it surfaces immediately instead of burning the full ~2-minute retry
/// budget re-polling a lost cause.
pub async fn wait_for_workflow(
    client: &reqwest::Client,
    configs: &Configs,
    workflow_id: String,
) -> Result<(), WorkflowError> {
    wait_for_workflow_up_to(client, configs, workflow_id, 120).await
}

/// [`wait_for_workflow`] with a caller-chosen attempt budget (1s per attempt)
/// for operations whose server-side duration is data-dependent -- e.g. a
/// backup restore replicating a whole volume.
pub async fn wait_for_workflow_up_to(
    client: &reqwest::Client,
    configs: &Configs,
    workflow_id: String,
    max_attempts: u32,
) -> Result<(), WorkflowError> {
    let backboard = configs.get_backboard();

    let result = retry_with_backoff(
        RetryConfig {
            max_attempts, // ~1s per attempt
            initial_delay_ms: 1000,
            max_delay_ms: 2000,
            backoff_multiplier: 1.0,
            on_retry: None,
        },
        || {
            let client = client.clone();
            let backboard = backboard.clone();
            let workflow_id = workflow_id.clone();
            async move {
                let result = match post_graphql::<queries::WorkflowStatus, _>(
                    &client,
                    backboard,
                    queries::workflow_status::Variables { workflow_id },
                )
                .await
                {
                    Ok(result) => result,
                    // An auth refusal is deterministic -- retrying can't heal
                    // it (e.g. a workflow type that doesn't register the
                    // queries `workflowStatus` authorizes against). Fail fast
                    // instead of silently polling out the whole budget.
                    Err(
                        err @ (crate::errors::RailwayError::Unauthorized
                        | crate::errors::RailwayError::UnauthorizedToken(_)
                        | crate::errors::RailwayError::UnauthorizedLogin),
                    ) => {
                        return Ok(TerminalPoll::Failed(format!(
                            "the workflow's status can't be polled ({err}); it keeps running server-side"
                        )));
                    }
                    Err(err) => return Err(err.into()),
                };

                use queries::workflow_status::WorkflowStatus;
                match result.workflow_status.status {
                    WorkflowStatus::Complete => Ok(TerminalPoll::Complete),
                    WorkflowStatus::Error => {
                        let error_msg = result
                            .workflow_status
                            .error
                            .filter(|e| !e.is_empty())
                            .unwrap_or_else(|| "Unknown error".to_string());
                        Ok(TerminalPoll::Failed(error_msg))
                    }
                    WorkflowStatus::NotFound => Err(WorkflowError::NotFound.into()),
                    WorkflowStatus::Running | WorkflowStatus::Other(_) => {
                        Err(WorkflowError::Timeout.into())
                    }
                }
            }
        },
    )
    .await;

    match result {
        Ok(TerminalPoll::Complete) => Ok(()),
        Ok(TerminalPoll::Failed(message)) => Err(WorkflowError::Failed(message)),
        Err(e) => Err(e
            .downcast::<WorkflowError>()
            .unwrap_or_else(|e| WorkflowError::Failed(e.to_string()))),
    }
}

